68	+import { useState } from "react";
69	+import { useAuth } from "./auth/AuthContext";
70	+import { LoginScreen } from "./screens/LoginScreen";
71	+import { MissionListScreen } from "./screens/MissionListScreen";
72	+import { MissionCreateScreen } from "./screens/MissionCreateScreen";
73	+import { MissionDetailScreen } from "./screens/MissionDetailScreen";
74	+import { MyAssignmentsScreen } from "./screens/MyAssignmentsScreen";
75	+import { CrewListScreen } from "./screens/CrewListScreen";
76	+import { CrewProfileScreen } from "./screens/CrewProfileScreen";
77	+import { SkillsScreen } from "./screens/SkillsScreen";
78	+import { MyProfileScreen } from "./screens/MyProfileScreen";
79	+import {
80	+  AssignmentsNavIcon,
81	+  CrewNavIcon,
82	+  MissionsNavIcon,
83	+  ProfileNavIcon,
84	+  Sidebar,
85	+  SkillsNavIcon,
86	+  type NavItem,
87	+} from "./components/Sidebar";
88	+import { Spinner } from "./components/Spinner";
89	+
90	+type DirectorLeadSection = "missions" | "crew" | "skills";
91	+
92	+const DIRECTOR_LEAD_NAV: NavItem[] = [
93	+  { key: "missions", label: "Missions", icon: MissionsNavIcon },
94	+  { key: "crew", label: "Crew", icon: CrewNavIcon },
95	+  { key: "skills", label: "Skills", icon: SkillsNavIcon },
96	+];
97	+
98	+/** Director / Mission Lead: Missions (existing), Crew (roster -> read-only
99	+ * profile, FR-4), Skills (org taxonomy, FR-5). No router — each is a
100	+ * sibling top-level section, and within Missions/Crew a `useState` stack
101	+ * two screens deep at most (PRD §7: "no routing depth"). */
102	+function DirectorLeadApp() {
103	+  const [section, setSection] = useState<DirectorLeadSection>("missions");
104	+  const [selectedMissionId, setSelectedMissionId] = useState<number | null>(null);
105	+  const [isCreatingMission, setIsCreatingMission] = useState(false);
106	+  const [selectedCrewId, setSelectedCrewId] = useState<number | null>(null);
107	+
108	+  function selectSection(key: string) {
109	+    setSection(key as DirectorLeadSection);
110	+    // Leaving a section resets its drill-down so coming back starts at the list.
111	+    setSelectedMissionId(null);
112	+    setIsCreatingMission(false);
113	+    setSelectedCrewId(null);
114	+  }
115	+
116	+  let content;
117	+  if (section === "missions") {
118	+    if (isCreatingMission) {
119	+      content = (
120	+        <MissionCreateScreen
121	+          onCreated={(missionId) => {
122	+            setIsCreatingMission(false);
123	+            setSelectedMissionId(missionId);
124	+          }}
125	+          onCancel={() => setIsCreatingMission(false)}
126	+        />
127	+      );
128	+    } else if (selectedMissionId === null) {
129	+      content = (
130	+        <MissionListScreen onSelectMission={setSelectedMissionId} onCreateMission={() => setIsCreatingMission(true)} />
131	+      );
132	+    } else {
133	+      content = <MissionDetailScreen missionId={selectedMissionId} onBack={() => setSelectedMissionId(null)} />;
134	+    }
135	+  } else if (section === "crew") {
136	+    content =
137	+      selectedCrewId === null ? (
138	+        <CrewListScreen onSelectCrew={setSelectedCrewId} />
139	+      ) : (
140	+        <CrewProfileScreen crewId={selectedCrewId} onBack={() => setSelectedCrewId(null)} />
141	+      );
142	+  } else {
143	+    content = <SkillsScreen />;
144	+  }
145	+
146	+  return (
147	+    <div className="flex min-h-screen">
148	+      <Sidebar items={DIRECTOR_LEAD_NAV} activeKey={section} onSelect={selectSection} />
149	+      {content}
150	+    </div>
151	+  );
152	+}
153	+
154	+type CrewMemberSection = "assignments" | "profile";
155	+
156	+const CREW_MEMBER_NAV: NavItem[] = [
157	+  { key: "assignments", label: "My assignments", icon: AssignmentsNavIcon },
158	+  { key: "profile", label: "My profile", icon: ProfileNavIcon },
159	+];
160	+
161	+/** Crew Member: My Assignments (existing) + My Profile (new: self-service
162	+ * profile/skills/availability, FR-4/FR-6/FR-7). */
163	+function CrewMemberApp() {
164	+  const [section, setSection] = useState<CrewMemberSection>("assignments");
165	+
166	+  return (
167	+    <div className="flex min-h-screen">
168	+      <Sidebar items={CREW_MEMBER_NAV} activeKey={section} onSelect={(key) => setSection(key as CrewMemberSection)} />
169	+      {section === "assignments" ? <MyAssignmentsScreen /> : <MyProfileScreen />}
170	+    </div>
171	+  );
172	+}
173	+
174	+export default function App() {
175	+  const { status, user } = useAuth();
176	+
177	+  if (status === "loading") {
178	+    return (
179	+      <div className="flex min-h-screen items-center justify-center bg-bg">
180	+        <Spinner className="h-6 w-6 text-text-3" />
181	+      </div>
182	+    );
183	+  }
184	+
185	+  if (status === "unauthenticated" || !user) {
186	+    return <LoginScreen />;
187	+  }
188	+
189	+  // Role-conditional nav off the logged-in user's role (§10 #23, extended
190	+  // for T8b): Director/Mission Lead get Missions/Crew/Skills; Crew Member
191	+  // gets My Assignments/My Profile.
192	+  if (user.role === "crew_member") {
193	+    return <CrewMemberApp />;
194	+  }
195	+  return <DirectorLeadApp />;
196	+}
197	diff --git a/web/src/api/client.ts b/web/src/api/client.ts
198	new file mode 100644
199	index 0000000..47d93f2
200	--- /dev/null
201	+++ b/web/src/api/client.ts
202	@@ -0,0 +1,194 @@
203	+/**
204	+ * Typed RPC-flavored client over the FastAPI backend.
205	+ *
206	+ * Judgment call (T8, §10 #21): the PRD's "typed client generated from the
207	+ * API's schema" is satisfied here with hand-written types (api/types.ts)
208	+ * instead of a generated OpenAPI client. For 8 routes across 4 resources,
209	+ * adding an `openapi-typescript` (or similar) codegen step to the build
210	+ * would be more tooling than the showcase needs; the request/response
211	+ * shapes were read directly from `api/routes/*.py` so they stay accurate.
212	+ * Calls still read RPC-style — `api.mission.approve(id)` — which is the
213	+ * actual DX goal; only the type *source* differs from the PRD's suggestion.
214	+ * If this app grows past a showcase, generating from `/openapi.json` is the
215	+ * first thing to revisit.
216	+ */
217	+
218	+import type {
219	+  Assignment,
220	+  AvailabilityWindow,
221	+  CrewProfile,
222	+  CrewRosterEntry,
223	+  CrewSkill,
224	+  FieldError,
225	+  LoginResponse,
226	+  Mission,
227	+  MissionDetail,
228	+  RequirementMatch,
229	+  Skill,
230	+  User,
231	+} from "./types";
232	+
233	+const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL as string | undefined) ?? "http://localhost:8000";
234	+
235	+/** Thrown for any non-2xx response. Carries the parsed `detail` from the
236	+ * API's error envelope (api/errors.py): a plain string for most errors, or
237	+ * a list of field errors for 422 validation failures. */
238	+export class ApiError extends Error {
239	+  readonly status: number;
240	+  readonly fieldErrors?: FieldError[];
241	+
242	+  constructor(status: number, detail: unknown) {
243	+    const { message, fieldErrors } = ApiError.parseDetail(detail);
244	+    super(message);
245	+    this.name = "ApiError";
246	+    this.status = status;
247	+    this.fieldErrors = fieldErrors;
248	+  }
249	+
250	+  private static parseDetail(detail: unknown): { message: string; fieldErrors?: FieldError[] } {
251	+    if (typeof detail === "string" && detail.length > 0) {
252	+      return { message: detail };
253	+    }
254	+    if (Array.isArray(detail)) {
255	+      const fieldErrors = detail as FieldError[];
256	+      return {
257	+        message: fieldErrors.map((e) => `${e.field}: ${e.message}`).join("; ") || "Invalid request.",
258	+        fieldErrors,
259	+      };
260	+    }
261	+    return { message: "Something went wrong. Please try again." };
262	+  }
263	+}
264	+
265	+type TokenGetter = () => string | null;
266	+
267	+let getToken: TokenGetter = () => null;
268	+
269	+/** Wired up once by AuthContext so the client always sends the current
270	+ * token without every call site having to thread it through. */
271	+export function configureAuthToken(getter: TokenGetter): void {
272	+  getToken = getter;
273	+}
274	+
275	+/** Called on every 401 so the app can drop a stale/invalid token and
276	+ * bounce back to the login screen. Wired up by AuthContext. */
277	+let onUnauthorized: () => void = () => {};
278	+export function configureUnauthorizedHandler(handler: () => void): void {
279	+  onUnauthorized = handler;
280	+}
281	+
282	+async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
283	+  const token = getToken();
284	+  const headers = new Headers(init.headers);
285	+  headers.set("Content-Type", "application/json");
286	+  if (token) headers.set("Authorization", `Bearer ${token}`);
287	+
288	+  const res = await fetch(`${API_BASE_URL}${path}`, { ...init, headers });
289	+
290	+  if (res.status === 204) {
291	+    return undefined as T;
292	+  }
293	+
294	+  const text = await res.text();
295	+  let body: unknown = null;
296	+  if (text) {
297	+    try {
298	+      body = JSON.parse(text);
299	+    } catch {
300	+      body = text;
301	+    }
302	+  }
303	+
304	+  if (!res.ok) {
305	+    if (res.status === 401) onUnauthorized();
306	+    const detail = body && typeof body === "object" && "detail" in (body as Record<string, unknown>)
307	+      ? (body as Record<string, unknown>).detail
308	+      : body;
309	+    throw new ApiError(res.status, detail);
310	+  }
311	+
312	+  return body as T;
313	+}
314	+
315	+const get = <T>(path: string): Promise<T> => request<T>(path, { method: "GET" });
316	+const post = <T>(path: string, data?: unknown): Promise<T> =>
317	+  request<T>(path, { method: "POST", body: data === undefined ? undefined : JSON.stringify(data) });
318	+const patch = <T>(path: string, data: unknown): Promise<T> =>
319	+  request<T>(path, { method: "PATCH", body: JSON.stringify(data) });
320	+const put = <T>(path: string, data: unknown): Promise<T> =>
321	+  request<T>(path, { method: "PUT", body: JSON.stringify(data) });
322	+const del = <T>(path: string): Promise<T> => request<T>(path, { method: "DELETE" });
323	+
324	+export const api = {
325	+  auth: {
326	+    login: (email: string, password: string): Promise<LoginResponse> =>
327	+      post<LoginResponse>("/auth/login", { email, password }),
328	+    whoami: (): Promise<User> => get<User>("/auth/whoami"),
329	+  },
330	+  mission: {
331	+    list: (): Promise<Mission[]> => get<Mission[]>("/missions"),
332	+    get: (id: number): Promise<MissionDetail> => get<MissionDetail>(`/missions/${id}`),
333	+    /** Director or Mission Lead (api/routes/mission.py's `require_role`);
334	+     * starts in `draft` (FR-8). `startDate`/`endDate` are `YYYY-MM-DD`. */
335	+    create: (input: { name: string; description: string; startDate: string; endDate: string }): Promise<Mission> =>
