556	diff --git a/web/src/auth/AuthContext.tsx b/web/src/auth/AuthContext.tsx
557	new file mode 100644
558	index 0000000..c2e9a94
559	--- /dev/null
560	+++ b/web/src/auth/AuthContext.tsx
561	@@ -0,0 +1,98 @@
562	+import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
563	+import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
564	+import { ApiError, api, configureAuthToken, configureUnauthorizedHandler } from "../api/client";
565	+import type { User } from "../api/types";
566	+
567	+const TOKEN_STORAGE_KEY = "mission-control:token";
568	+
569	+interface AuthContextValue {
570	+  user: User | null;
571	+  /** "loading": token present, still confirming it with the API.
572	+   * "unauthenticated": no token, or it turned out invalid/expired.
573	+   * "authenticated": token confirmed, `user` is populated. */
574	+  status: "loading" | "authenticated" | "unauthenticated";
575	+  login: (email: string, password: string) => Promise<void>;
576	+  isLoggingIn: boolean;
577	+  loginError: string | null;
578	+  logout: () => void;
579	+}
580	+
581	+const AuthContext = createContext<AuthContextValue | null>(null);
582	+
583	+export function AuthProvider({ children }: { children: ReactNode }) {
584	+  const queryClient = useQueryClient();
585	+  const [token, setToken] = useState<string | null>(() => localStorage.getItem(TOKEN_STORAGE_KEY));
586	+
587	+  const logout = useCallback(() => {
588	+    localStorage.removeItem(TOKEN_STORAGE_KEY);
589	+    setToken(null);
590	+    queryClient.clear();
591	+  }, [queryClient]);
592	+
593	+  // Deliberately NOT a useEffect: a login (or logout) can swap the tree
594	+  // from <LoginScreen> to the authenticated screens in the same commit,
595	+  // whose queries fire from *their own* mount effects. React runs effects
596	+  // bottom-up (children before parents), so if this ran in a useEffect
597	+  // here, a freshly-mounted child's first fetch could beat this effect and
598	+  // go out with a stale (or no) token. Setting it during render instead —
599	+  // a plain synchronous assignment to a module-level function reference,
600	+  // not a state update — guarantees it's current before any effect in this
601	+  // commit runs.
602	+  configureAuthToken(() => token);
603	+  configureUnauthorizedHandler(logout);
604	+
605	+  const whoami = useQuery({
606	+    queryKey: ["auth", "whoami"],
607	+    queryFn: api.auth.whoami,
608	+    enabled: token !== null,
609	+    retry: false,
610	+  });
611	+
612	+  // An expired/revoked token: whoami 401s (which also fires logout via
613	+  // configureUnauthorizedHandler above, but that's async — this covers the
614	+  // render before that runs).
615	+  useEffect(() => {
616	+    if (token !== null && whoami.isError) {
617	+      logout();
618	+    }
619	+  }, [token, whoami.isError, logout]);
620	+
621	+  const loginMutation = useMutation({
622	+    mutationFn: ({ email, password }: { email: string; password: string }) => api.auth.login(email, password),
623	+    onSuccess: (data) => {
624	+      localStorage.setItem(TOKEN_STORAGE_KEY, data.token);
625	+      queryClient.setQueryData(["auth", "whoami"], data.user);
626	+      setToken(data.token);
627	+    },
628	+  });
629	+
630	+  const login = useCallback(
631	+    async (email: string, password: string) => {
632	+      await loginMutation.mutateAsync({ email, password });
633	+    },
634	+    [loginMutation],
635	+  );
636	+
637	+  const status: AuthContextValue["status"] =
638	+    token === null ? "unauthenticated" : whoami.data ? "authenticated" : "loading";
639	+
640	+  const value = useMemo<AuthContextValue>(
641	+    () => ({
642	+      user: whoami.data ?? null,
643	+      status,
644	+      login,
645	+      isLoggingIn: loginMutation.isPending,
646	+      loginError: loginMutation.error instanceof ApiError ? loginMutation.error.message : null,
647	+      logout,
648	+    }),
649	+    [whoami.data, status, login, loginMutation.isPending, loginMutation.error, logout],
650	+  );
651	+
652	+  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
653	+}
654	+
655	+export function useAuth(): AuthContextValue {
656	+  const ctx = useContext(AuthContext);
657	+  if (!ctx) throw new Error("useAuth must be used within an AuthProvider");
658	+  return ctx;
659	+}
