966	+/** Formats an ISO `YYYY-MM-DD` date as e.g. "Mar 4". */
967	+export function formatDate(isoDate: string): string {
968	+  // Avoid the UTC/local timezone-shift trap `new Date("2026-03-04")` has —
969	+  // append a time so it's parsed as local midnight, not UTC midnight.
970	+  const date = new Date(`${isoDate}T00:00:00`);
971	+  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
972	+}
973	+
974	+/** Formats a start/end date pair as e.g. "Mar 4 – Mar 16". */
975	+export function formatDateRange(startIso: string, endIso: string): string {
976	+  return `${formatDate(startIso)} – ${formatDate(endIso)}`;
977	+}
978	+
979	+/** Up to two uppercase initials from a display name, for avatar chips. */
980	+export function initials(name: string): string {
981	+  const parts = name.trim().split(/\s+/).filter(Boolean);
982	+  if (parts.length === 0) return "?";
983	+  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase();
984	+  return `${parts[0]![0]}${parts[parts.length - 1]![0]}`.toUpperCase();
985	+}
986	+
