+/**
+ * Hand-written types mirroring the Pydantic response/request models in
+ * `api/routes/*.py` (auth, mission, match, assignment). See client.ts for
+ * why this is hand-written rather than generated from the OpenAPI schema.
+ */
+
+export type Role = "director" | "mission_lead" | "crew_member";
+
+export type MissionStatus =
+  | "draft"
+  | "pending_approval"
+  | "approved"
+  | "active"
+  | "completed"
+  | "cancelled";
+
+export type AssignmentStatus = "proposed" | "confirmed" | "declined";
+
+export interface User {
+  id: number;
+  org_id: number;
+  email: string;
+  name: string;
+  role: Role;
+}
+
+export interface LoginResponse {
+  token: string;
+  user: User;
+}
+
+export interface Mission {
+  id: number;
+  org_id: number;
+  created_by: number;
+  name: string;
+  description: string;
+  start_date: string;
+  end_date: string;
+  status: MissionStatus;
+}
+
+export interface Requirement {
+  id: number;
+  mission_id: number;
+  skill_id: number;
+  skill_name: string;
+  min_proficiency: number;
+  headcount: number;
+  confirmed: number;
+}
+
+export interface MissionDetail extends Mission {
+  requirements: Requirement[];
+}
+
+export interface MatchCandidate {
+  crew_id: number;
+  crew_name: string;
+  score: number;
+  proficiency_surplus_score: number;
+  workload_score: number;
+  availability_margin_score: number;
+  breakdown: string;
+}
+
+export interface RequirementMatch {
+  requirement_id: number;
+  skill_id: number;
+  min_proficiency: number;
+  headcount: number;
+  candidates: MatchCandidate[];
+}
+
+export interface Assignment {
+  id: number;
+  mission_id: number;
+  requirement_id: number;
+  crew_id: number;
+  proposed_by: number;
+  status: AssignmentStatus;
+  proposed_at: string;
+  responded_at: string | null;
+}
+
+/** Field-level shape the API's 422 handler emits (api/errors.py). */
+export interface FieldError {
+  field: string;
+  message: string;
+}
+
+/** One entry in a Director/Lead's org roster (`GET /crew`, api/routes/crew.py). */
+export interface CrewRosterEntry {
+  user_id: number;
+  name: string;
+  email: string;
+  skill_count: number;
+}
+
+/** A skill proficiency held by a crew member, as it appears on their profile. */
+export interface CrewSkill {
+  skill_id: number;
+  skill_name: string;
+  proficiency: number;
+}
+
+/** `GET /crew/{id}/profile` response — self, or (Director/Lead) another
+ * crew member's, read-only in that case. */
+export interface CrewProfile {
+  user_id: number;
+  org_id: number;
+  name: string;
+  email: string;
+  contact: string | null;
+  bio: string | null;
+  skills: CrewSkill[];
+}
+
+/** An org-scoped skill taxonomy entry (`/skills`, FR-5). */
+export interface Skill {
+  id: number;
+  org_id: number;
+  name: string;
+  category: string | null;
+}
+
+/** An unavailability window on a crew member's profile (FR-7). Absent any
+ * window, a crew member defaults to available. */
+export interface AvailabilityWindow {
+  id: number;
+  crew_id: number;
+  start_date: string;
+  end_date: string;
+}
diff --git a/web/src/auth/AuthContext.tsx b/web/src/auth/AuthContext.tsx
new file mode 100644
index 0000000..c2e9a94
--- /dev/null
+++ b/web/src/auth/AuthContext.tsx
@@ -0,0 +1,98 @@
+import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
+import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
+import { ApiError, api, configureAuthToken, configureUnauthorizedHandler } from "../api/client";
+import type { User } from "../api/types";
+
+const TOKEN_STORAGE_KEY = "mission-control:token";
+
+interface AuthContextValue {
+  user: User | null;
+  /** "loading": token present, still confirming it with the API.
+   * "unauthenticated": no token, or it turned out invalid/expired.
+   * "authenticated": token confirmed, `user` is populated. */
+  status: "loading" | "authenticated" | "unauthenticated";
+  login: (email: string, password: string) => Promise<void>;
+  isLoggingIn: boolean;
+  loginError: string | null;
+  logout: () => void;
+}
+
+const AuthContext = createContext<AuthContextValue | null>(null);
+
+export function AuthProvider({ children }: { children: ReactNode }) {
+  const queryClient = useQueryClient();
+  const [token, setToken] = useState<string | null>(() => localStorage.getItem(TOKEN_STORAGE_KEY));
+
+  const logout = useCallback(() => {
+    localStorage.removeItem(TOKEN_STORAGE_KEY);
+    setToken(null);
+    queryClient.clear();
+  }, [queryClient]);
+
+  // Deliberately NOT a useEffect: a login (or logout) can swap the tree
+  // from <LoginScreen> to the authenticated screens in the same commit,
+  // whose queries fire from *their own* mount effects. React runs effects
+  // bottom-up (children before parents), so if this ran in a useEffect
+  // here, a freshly-mounted child's first fetch could beat this effect and
+  // go out with a stale (or no) token. Setting it during render instead —
+  // a plain synchronous assignment to a module-level function reference,
+  // not a state update — guarantees it's current before any effect in this
+  // commit runs.
+  configureAuthToken(() => token);
+  configureUnauthorizedHandler(logout);
+
+  const whoami = useQuery({
+    queryKey: ["auth", "whoami"],
+    queryFn: api.auth.whoami,
+    enabled: token !== null,
+    retry: false,
+  });
+
+  // An expired/revoked token: whoami 401s (which also fires logout via
+  // configureUnauthorizedHandler above, but that's async — this covers the
+  // render before that runs).
+  useEffect(() => {
+    if (token !== null && whoami.isError) {
+      logout();
+    }
+  }, [token, whoami.isError, logout]);
+
+  const loginMutation = useMutation({
+    mutationFn: ({ email, password }: { email: string; password: string }) => api.auth.login(email, password),
+    onSuccess: (data) => {
+      localStorage.setItem(TOKEN_STORAGE_KEY, data.token);
+      queryClient.setQueryData(["auth", "whoami"], data.user);
+      setToken(data.token);
+    },
+  });
+
+  const login = useCallback(
+    async (email: string, password: string) => {
+      await loginMutation.mutateAsync({ email, password });
+    },
+    [loginMutation],
+  );
+
+  const status: AuthContextValue["status"] =
+    token === null ? "unauthenticated" : whoami.data ? "authenticated" : "loading";
+
+  const value = useMemo<AuthContextValue>(
+    () => ({
+      user: whoami.data ?? null,
+      status,
+      login,
+      isLoggingIn: loginMutation.isPending,
+      loginError: loginMutation.error instanceof ApiError ? loginMutation.error.message : null,
+      logout,
+    }),
+    [whoami.data, status, login, loginMutation.isPending, loginMutation.error, logout],
+  );
+
+  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
+}
+
+export function useAuth(): AuthContextValue {
+  const ctx = useContext(AuthContext);
+  if (!ctx) throw new Error("useAuth must be used within an AuthProvider");
+  return ctx;
+}
