+import { useMemo, useState } from "react";
+import { useQuery } from "@tanstack/react-query";
+import { api } from "../api/client";
+import type { Mission, MissionStatus } from "../api/types";
+import { MissionStatusBadge } from "../components/StatusBadge";
+import { ErrorBanner } from "../components/ErrorBanner";
+import { formatDateRange, missionStatusLabel } from "../lib/format";
+
+const STATUS_FILTERS: MissionStatus[] = [
+  "draft",
+  "pending_approval",
+  "approved",
+  "active",
+  "completed",
+  "cancelled",
+];
+
+// Stable reference so `missions` doesn't change identity on every render
+// while the query is pending (a fresh `[]` literal would).
+const EMPTY_MISSIONS: Mission[] = [];
+
+function MissionRowSkeleton() {
+  return (
+    <div className="grid grid-cols-[2.4fr_1.3fr_1fr_32px] items-center gap-3 border-b border-border px-5 py-4">
+      <div className="h-4 w-40 animate-pulse rounded bg-surface-2" />
+      <div className="h-4 w-24 animate-pulse rounded bg-surface-2" />
+      <div className="h-6 w-20 animate-pulse rounded-full bg-surface-2" />
+      <div />
+    </div>
+  );
+}
+
+export function MissionListScreen({
+  onSelectMission,
+  onCreateMission,
+}: {
+  onSelectMission: (missionId: number) => void;
+  onCreateMission: () => void;
+}) {
+  const missionsQuery = useQuery({ queryKey: ["missions"], queryFn: api.mission.list });
+  const [search, setSearch] = useState("");
+  const [statusFilter, setStatusFilter] = useState<MissionStatus | "all">("all");
+
+  const missions = missionsQuery.data ?? EMPTY_MISSIONS;
+
+  const counts = useMemo(() => {
+    const byStatus: Partial<Record<MissionStatus, number>> = {};
+    for (const m of missions) byStatus[m.status] = (byStatus[m.status] ?? 0) + 1;
+    return byStatus;
+  }, [missions]);
+
+  const filtered = useMemo(() => {
+    return missions.filter((m: Mission) => {
+      if (statusFilter !== "all" && m.status !== statusFilter) return false;
+      if (search.trim() && !m.name.toLowerCase().includes(search.trim().toLowerCase())) return false;
+      return true;
+    });
+  }, [missions, statusFilter, search]);
+
+  return (
+    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-8">
+      <div className="flex items-start justify-between gap-4">
+        <div>
+          <div className="text-[22px] font-bold">Missions</div>
+          <div className="mt-0.5 text-[13px] text-text-2">
+            {missionsQuery.isSuccess ? `${missions.length} mission${missions.length === 1 ? "" : "s"} in your organization` : " "}
+          </div>
+        </div>
+        <button
+          type="button"
+          onClick={onCreateMission}
+          className="flex flex-none items-center gap-1.5 rounded-md bg-accent px-4 py-2.5 text-[13px] font-semibold text-white"
+        >
+          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.25">
+            <path d="M12 5v14M5 12h14" />
+          </svg>
+          New mission
+        </button>
+      </div>
+
+      <div className="flex flex-wrap items-center gap-2.5">
+        <div className="relative">
+          <svg
+            width="15"
+            height="15"
+            viewBox="0 0 24 24"
+            fill="none"
+            stroke="var(--color-text-3)"
+            strokeWidth="2"
+            className="pointer-events-none absolute left-[11px] top-1/2 -translate-y-1/2"
+          >
+            <circle cx="11" cy="11" r="7" />
+            <path d="M21 21l-4-4" />
+          </svg>
+          <input
+            type="text"
+            value={search}
+            onChange={(e) => setSearch(e.target.value)}
+            placeholder="Search missions"
+            aria-label="Search missions"
+            className="w-64 rounded-md border border-border bg-surface py-2.5 pl-8 pr-3 text-[13.5px] text-text placeholder:text-text-3 focus:border-accent focus:outline-none"
+          />
+        </div>
+        <div className="flex-1" />
+        <button
+          type="button"
+          onClick={() => setStatusFilter("all")}
+          className={`rounded-full border px-3 py-1.5 text-[12.5px] font-medium ${
+            statusFilter === "all" ? "border-transparent bg-accent-2 text-accent-dark" : "border-border bg-surface text-text-2"
+          }`}
+        >
+          All · {missions.length}
+        </button>
+        {STATUS_FILTERS.map((status) => (
+          <button
+            key={status}
+            type="button"
+            onClick={() => setStatusFilter(status)}
+            className={`rounded-full border px-3 py-1.5 text-[12.5px] font-medium ${
+              statusFilter === status ? "border-transparent bg-accent-2 text-accent-dark" : "border-border bg-surface text-text-2"
+            }`}
+          >
+            {missionStatusLabel(status)} · {counts[status] ?? 0}
+          </button>
+        ))}
+      </div>
+
+      {missionsQuery.isError && (
+        <ErrorBanner
+          message={missionsQuery.error instanceof Error ? missionsQuery.error.message : "Couldn't load missions."}
+          onRetry={() => missionsQuery.refetch()}
+        />
+      )}
+
+      <div className="overflow-hidden rounded-[10px] border border-border bg-surface">
+        <div className="grid grid-cols-[2.4fr_1.3fr_1fr_32px] gap-3 border-b border-border px-5 py-3 text-[11.5px] font-semibold uppercase tracking-wide text-text-3">
+          <div>Mission</div>
+          <div>Dates</div>
+          <div>Status</div>
+          <div />
+        </div>
+
+        {missionsQuery.isPending && (
+          <>
+            <MissionRowSkeleton />
+            <MissionRowSkeleton />
+            <MissionRowSkeleton />
+          </>
+        )}
+
+        {missionsQuery.isSuccess && filtered.length === 0 && (
+          <div className="px-5 py-10 text-center text-sm text-text-3">
+            {missions.length === 0 ? "No missions yet." : "No missions match your search."}
+          </div>
+        )}
+
+        {filtered.map((mission) => (
+          <button
+            key={mission.id}
+            type="button"
+            onClick={() => onSelectMission(mission.id)}
+            className="grid w-full grid-cols-[2.4fr_1.3fr_1fr_32px] items-center gap-3 border-b border-border px-5 py-4 text-left last:border-b-0 hover:bg-surface-2"
+          >
+            <div className="min-w-0">
+              <div className="truncate text-sm font-semibold">{mission.name}</div>
+            </div>
+            <div className="text-[13px] text-text-2">{formatDateRange(mission.start_date, mission.end_date)}</div>
+            <div>
+              <MissionStatusBadge status={mission.status} />
+            </div>
+            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--color-text-3)" strokeWidth="1.75">
+              <path d="M9 6l6 6-6 6" />
+            </svg>
+          </button>
+        ))}
+      </div>
+    </div>
+  );
+}
diff --git a/web/src/screens/MyAssignmentsScreen.tsx b/web/src/screens/MyAssignmentsScreen.tsx
new file mode 100644
index 0000000..86f42f1
--- /dev/null
+++ b/web/src/screens/MyAssignmentsScreen.tsx
@@ -0,0 +1,177 @@
+import { useMemo } from "react";
+import { useMutation, useQueries, useQuery, useQueryClient } from "@tanstack/react-query";
+import { ApiError, api } from "../api/client";
+import type { Assignment, AssignmentStatus, MissionDetail } from "../api/types";
+import { AssignmentStatusBadge } from "../components/StatusBadge";
+import { ErrorBanner } from "../components/ErrorBanner";
+import { Spinner } from "../components/Spinner";
+import { formatDate, formatDateRange } from "../lib/format";
+
+function errorMessage(error: unknown, fallback: string): string {
+  return error instanceof ApiError ? error.message : fallback;
+}
+
+// proposed needs a decision first, then confirmed, then declined history last.
+const STATUS_ORDER: Record<AssignmentStatus, number> = { proposed: 0, confirmed: 1, declined: 2 };
+
+interface RespondVars {
+  assignmentId: number;
+  action: "accept" | "decline";
+}
+
+export function MyAssignmentsScreen() {
+  const queryClient = useQueryClient();
+
+  const assignmentsQuery = useQuery({ queryKey: ["assignments"], queryFn: api.assignment.list });
+  const assignments = useMemo(
+    () => [...(assignmentsQuery.data ?? [])].sort((a, b) => STATUS_ORDER[a.status] - STATUS_ORDER[b.status]),
+    [assignmentsQuery.data],
+  );
+
+  const missionIds = useMemo(() => Array.from(new Set(assignments.map((a) => a.mission_id))), [assignments]);
+
+  const missionQueries = useQueries({
+    queries: missionIds.map((id) => ({
+      queryKey: ["mission", id],
+      queryFn: () => api.mission.get(id),
+      enabled: assignmentsQuery.isSuccess,
+    })),
+  });
+  const missionById = new Map<number, MissionDetail>();
+  missionQueries.forEach((q, i) => {
+    if (q.data) missionById.set(missionIds[i]!, q.data);
+  });
+  const missionsLoading = missionQueries.some((q) => q.isPending);
+
+  const respondMutation = useMutation({
+    mutationFn: (vars: RespondVars) => api.assignment.respond(vars.assignmentId, vars.action),
+    onMutate: async (vars) => {
+      await queryClient.cancelQueries({ queryKey: ["assignments"] });
+      const previous = queryClient.getQueryData<Assignment[]>(["assignments"]);
+      queryClient.setQueryData<Assignment[]>(["assignments"], (old) =>
+        (old ?? []).map((a) =>
+          a.id === vars.assignmentId
+            ? { ...a, status: vars.action === "accept" ? "confirmed" : "declined", responded_at: new Date().toISOString() }
+            : a,
+        ),
+      );
+      return { previous };
+    },
+    onError: (_err, _vars, context) => {
+      if (context?.previous) queryClient.setQueryData(["assignments"], context.previous);
+    },
+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["assignments"] }),
+  });
+
+  return (
+    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-8">
+      <div>
+        <div className="text-[22px] font-bold">My Assignments</div>
+        <div className="mt-0.5 text-[13px] text-text-2">Missions you've been proposed or confirmed for.</div>
+      </div>
+
+      {assignmentsQuery.isError && (
+        <ErrorBanner
+          message={errorMessage(assignmentsQuery.error, "Couldn't load your assignments.")}
+          onRetry={() => assignmentsQuery.refetch()}
+        />
+      )}
+
+      {assignmentsQuery.isPending && (
+        <div className="flex flex-col gap-3">
+          {[0, 1, 2].map((i) => (
+            <div key={i} className="h-20 animate-pulse rounded-[10px] border border-border bg-surface" />
+          ))}
+        </div>
+      )}
+
+      {assignmentsQuery.isSuccess && assignments.length === 0 && (
+        <div className="rounded-[10px] border border-border bg-surface px-5 py-10 text-center text-sm text-text-3">
+          You haven't been proposed for any missions yet.
+        </div>
+      )}
+
+      <div className="flex flex-col gap-3">
+        {assignments.map((assignment) => {
+          const mission = missionById.get(assignment.mission_id);
+          const requirement = mission?.requirements.find((r) => r.id === assignment.requirement_id);
+          const isThisRow = respondMutation.variables?.assignmentId === assignment.id;
+          const isPending = respondMutation.isPending && isThisRow;
+          const isError = respondMutation.isError && isThisRow;
+
+          return (
+            <div
+              key={assignment.id}
+              className={`flex flex-col gap-2 rounded-[10px] border bg-surface px-[22px] py-[18px] ${
+                assignment.status === "proposed" ? "border-pending" : "border-border"
+              } ${assignment.status === "declined" ? "bg-surface-2 opacity-65" : ""} ${isPending ? "opacity-75" : ""}`}
+            >
+              <div className="flex items-center gap-5">
+                <div className="flex-1">
+                  <div className="flex items-center gap-2.5">
+                    <div className="text-[15px] font-bold">{mission?.name ?? (missionsLoading ? "Loading…" : `Mission #${assignment.mission_id}`)}</div>
+                    <AssignmentStatusBadge status={assignment.status} />
+                  </div>
+                  <div className="mt-1 text-[12.5px] text-text-2">
+                    {mission ? formatDateRange(mission.start_date, mission.end_date) : ""}
+                    {requirement ? ` · matched on ${requirement.skill_name} (min level ${requirement.min_proficiency})` : ""}
+                  </div>
+                </div>
+
+                {isPending && (
+                  <div className="flex items-center gap-2 text-sm font-semibold text-text-2">
+                    <Spinner /> {respondMutation.variables?.action === "accept" ? "Accepting…" : "Declining…"}
+                  </div>
+                )}
+
+                {!isPending && assignment.status === "proposed" && (
+                  <div className="flex gap-2.5">
+                    <button
+                      type="button"
+                      onClick={() => respondMutation.mutate({ assignmentId: assignment.id, action: "accept" })}
+                      className="rounded-md bg-accent px-[18px] py-2 text-sm font-semibold text-white"
+                    >
+                      Accept
+                    </button>
+                    <button
+                      type="button"
+                      onClick={() => respondMutation.mutate({ assignmentId: assignment.id, action: "decline" })}
+                      className="rounded-md border border-border bg-surface px-[18px] py-2 text-sm font-semibold text-text-2"
+                    >
+                      Decline
+                    </button>
+                  </div>
+                )}
+
+                {!isPending && assignment.status === "confirmed" && (
+                  <div className="flex items-center gap-1.5 text-sm font-semibold text-approved">
+                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
+                      <circle cx="12" cy="12" r="9" />
+                      <path d="M8.5 12.5l2.3 2.3L16 10" />
+                    </svg>
+                    You're on this mission
+                  </div>
+                )}
+
+                {!isPending && assignment.status === "declined" && assignment.responded_at && (
+                  <div className="text-xs text-text-3">
+                    Declined {formatDate(assignment.responded_at.slice(0, 10))} — your response reopened this slot.
+                  </div>
+                )}
+              </div>
+
+              {isError && (
+                <ErrorBanner
+                  message={`Couldn't ${respondMutation.variables?.action} — ${errorMessage(respondMutation.error, "something went wrong.")}`}
+                  onRetry={() =>
+                    respondMutation.mutate({ assignmentId: assignment.id, action: respondMutation.variables!.action })
+                  }
+                />
+              )}
+            </div>
+          );
+        })}
+      </div>
+    </div>
+  );
+}
diff --git a/web/src/screens/MyProfileScreen.tsx b/web/src/screens/MyProfileScreen.tsx
new file mode 100644
index 0000000..5e28d54
--- /dev/null
+++ b/web/src/screens/MyProfileScreen.tsx
@@ -0,0 +1,541 @@
+import { useState } from "react";
+import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
+import { ApiError, api } from "../api/client";
+import type { AvailabilityWindow, CrewProfile } from "../api/types";
+import { useAuth } from "../auth/AuthContext";
+import { ErrorBanner } from "../components/ErrorBanner";
+import { Spinner } from "../components/Spinner";
+import { formatDate, proficiencyLabel } from "../lib/format";
+
+function errorMessage(error: unknown, fallback: string): string {
+  return error instanceof ApiError ? error.message : fallback;
+}
+
+const PROFICIENCY_LEVELS = [1, 2, 3, 4, 5];
+
+interface ProfilePatchVars {
+  name: string;
+  contact: string;
+  bio: string;
+}
+
+interface SkillSetVars {
+  skillId: number;
+  skillName: string;
+  proficiency: number;
+}
+
+interface WindowAddVars {
+  startDate: string;
+  endDate: string;
+}
+
+/** Crew Member self-service: view/edit own profile (FR-4), set skill
+ * proficiency (FR-6), and manage unavailability windows (FR-7). The one
+ * screen in this task with real forms/mutations — reuses the
+ * optimistic-update/loading/error pattern from MissionDetailScreen rather
+ * than inventing a new one. */
+export function MyProfileScreen() {
+  const { user } = useAuth();
+  const userId = user!.id;
+  const queryClient = useQueryClient();
+
+  const profileQuery = useQuery({ queryKey: ["crew", "profile", userId], queryFn: () => api.crew.profile(userId) });
+  const skillsQuery = useQuery({ queryKey: ["skills"], queryFn: api.skills.list });
+  const availabilityQuery = useQuery({
+    queryKey: ["crew", "availability", userId],
+    queryFn: () => api.crew.listAvailability(userId),
+  });
+
+  const [isEditingProfile, setIsEditingProfile] = useState(false);
+  const [nameField, setNameField] = useState("");
+  const [contactField, setContactField] = useState("");
+  const [bioField, setBioField] = useState("");
+
+  const [editingSkillId, setEditingSkillId] = useState<number | null>(null);
+  const [editingProficiency, setEditingProficiency] = useState(3);
+  const [newSkillId, setNewSkillId] = useState("");
+  const [newProficiency, setNewProficiency] = useState(3);
+
+  const [windowStart, setWindowStart] = useState("");
+  const [windowEnd, setWindowEnd] = useState("");
+
+  const profileMutation = useMutation({
+    mutationFn: (vars: ProfilePatchVars) =>
+      api.crew.updateProfile(userId, { name: vars.name, contact: vars.contact, bio: vars.bio }),
+    onMutate: async (vars) => {
+      await queryClient.cancelQueries({ queryKey: ["crew", "profile", userId] });
+      const previous = queryClient.getQueryData<CrewProfile>(["crew", "profile", userId]);
+      if (previous) {
+        queryClient.setQueryData<CrewProfile>(["crew", "profile", userId], {
+          ...previous,
+          name: vars.name,
+          contact: vars.contact,
+          bio: vars.bio,
+        });
+      }
+      return { previous };
+    },
+    onSuccess: () => setIsEditingProfile(false),
+    onError: (_err, _vars, context) => {
+      if (context?.previous) queryClient.setQueryData(["crew", "profile", userId], context.previous);
+    },
+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "profile", userId] }),
+  });
+
+  const skillMutation = useMutation({
+    mutationFn: (vars: SkillSetVars) => api.crew.setSkill(userId, vars.skillName, vars.proficiency),
+    onMutate: async (vars) => {
+      await queryClient.cancelQueries({ queryKey: ["crew", "profile", userId] });
+      const previous = queryClient.getQueryData<CrewProfile>(["crew", "profile", userId]);
+      if (previous) {
+        const held = previous.skills.some((s) => s.skill_id === vars.skillId);
+        const skills = held
+          ? previous.skills.map((s) => (s.skill_id === vars.skillId ? { ...s, proficiency: vars.proficiency } : s))
+          : [...previous.skills, { skill_id: vars.skillId, skill_name: vars.skillName, proficiency: vars.proficiency }];
+        queryClient.setQueryData<CrewProfile>(["crew", "profile", userId], { ...previous, skills });
+      }
+      return { previous };
+    },
+    onSuccess: () => {
+      setEditingSkillId(null);
+      setNewSkillId("");
+      setNewProficiency(3);
+    },
+    onError: (_err, _vars, context) => {
+      if (context?.previous) queryClient.setQueryData(["crew", "profile", userId], context.previous);
+    },
+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "profile", userId] }),
+  });
+
+  const addWindowMutation = useMutation({
+    mutationFn: (vars: WindowAddVars) => api.crew.addAvailability(userId, vars.startDate, vars.endDate),
+    onMutate: async (vars) => {
+      await queryClient.cancelQueries({ queryKey: ["crew", "availability", userId] });
+      const previous = queryClient.getQueryData<AvailabilityWindow[]>(["crew", "availability", userId]);
+      const optimistic: AvailabilityWindow = {
+        id: -Date.now(),
+        crew_id: userId,
+        start_date: vars.startDate,
+        end_date: vars.endDate,
+      };
+      queryClient.setQueryData<AvailabilityWindow[]>(["crew", "availability", userId], (old) => [
+        ...(old ?? []),
+        optimistic,
+      ]);
+      return { previous };
+    },
+    onSuccess: () => {
+      setWindowStart("");
+      setWindowEnd("");
+    },
+    onError: (_err, _vars, context) => {
+      if (context?.previous) queryClient.setQueryData(["crew", "availability", userId], context.previous);
+    },
+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["crew", "availability", userId] }),
+  });
+
+  const removeWindowMutation = useMutation({
+    mutationFn: (windowId: number) => api.crew.removeAvailability(userId, windowId),
+    onMutate: async (windowId) => {
+      await queryClient.cancelQueries({ queryKey: ["crew", "availability", userId] });
+      const previous = queryClient.getQueryData<AvailabilityWindow[]>(["crew", "availability", userId]);
+      queryClient.setQueryData<AvailabilityWindow[]>(["crew", "availability", userId], (old) =>
+        (old ?? []).filter((w) => w.id !== windowId),
+      );
+      return { previous };
